"""Synthetic training data for a thermal defect detector, generated by thermoscene from the EnergyPlus example models
(experiment E3: does a detector trained only in the virtual environment generalise to buildings it has never seen?).

Stages (each resumable; results under case_studies/detector/, which is git-ignored):

  select  For every example model that the corpus survey built (case_studies/corpus_scenes.json), find a conditioned
          zone with at least one exterior wall that has an insulation layer and room for a defect, and a geometry
          signature (number of zones, total floor area) that groups variants of the same building. One model per
          signature is kept, so no building geometry appears twice. Excluded: DElight models (scratch files collide in
          parallel) and the DOE medium office (case C of the paper, kept unseen for the agent test).
  build   Inject one or two insulation voids (0.4-1.4 m by 0.4-1.4 m, insulation replaced by an air cavity, clear of
          windows and doors) into exterior walls of the zone, simulate with EnergyPlus (two winter and two summer
          days, the weather file nearest to the site) and build the scene.
  render  Render VIEWS views per building from inside the zone: 60 % aimed at a void, the rest at other things in the
          room (walls, windows, diffusers, luminaires, occupants, desks), from 1-4 m at a robot's eye height, with the
          target off-centre, at a random time step, through a random unit of a random camera class. Each view is stored
          three ways at 120 x 160 pixels: the camera reading in the realistic scene, the reading of an ideal camera in
          an idealised scene (emissivity and diffuse reflection only), and the true surface temperature; plus the
          per-pixel defect mask.
  split   Assign signatures to train / validation / test (fixed seed).

    python case_studies/detector_data.py select|build|render|split|all [--jobs N] [--limit N]
"""
from __future__ import annotations

import argparse
import hashlib
import json
import multiprocessing as mp
import sys
import tempfile
import time
import traceback
from pathlib import Path

import numpy as np

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
OUT = ROOT / "case_studies" / "detector"
SEED = 2026
VIEWS = 40
POS_SHARE = 0.6
PRESETS = (("lepton35", 0.4), ("handheld_320", 0.4), ("drone_640", 0.2))
H, W = 120, 160
EXCLUDE = ("DElight", "MediumOffice", "OfficeMedium", "RefMedOff")        # case C geometry stays unseen
CLEAN = dict(angular_emissivity=False, specular_reflections=False, texture=dict(enabled=False),
             atmosphere_extinction_per_m=0.0)


# ------------------------------------------------------------------------------------------------ select
def _wall_rects(model, wall):
    """The wall's (width, height) in its own frame and the rectangles of its sub-surfaces, relative to its lower-left."""
    from thermoscene.scene.geometry import frame, to2d
    o, u, v, n = frame(wall["verts"])
    uv = to2d(wall["verts"], o, u, v)
    lo = uv.min(0)
    width, height = (uv.max(0) - lo).tolist()
    subs = []
    for s in model.subsurfaces(wall):
        q = to2d(s["verts"], o, u, v) - lo
        subs.append((*q.min(0).tolist(), *q.max(0).tolist()))
    return width, height, subs


def place_defect(width, height, subs, rng, tries=300):
    """[u0, u1, v0, v1] of a void clear of the sub-surfaces (0.15 m) and the wall edges (0.25 m), or None."""
    for _ in range(tries):
        w, h = rng.uniform(0.4, 1.4), rng.uniform(0.4, 1.4)
        if width < w + 0.5 or height < h + 0.5:
            continue
        u0 = rng.uniform(0.25, width - 0.25 - w)
        v0 = rng.uniform(0.25, min(height - 0.25 - h, 2.6))
        r = (u0, u0 + w, v0, v0 + h)
        if all(r[1] + 0.15 <= a or r[0] - 0.15 >= c or r[3] + 0.15 <= b or r[2] - 0.15 >= d for a, b, c, d in subs):
            return [round(x, 3) for x in r]
    return None


def select_one(idf: str) -> dict:
    from thermoscene import pipeline
    from thermoscene.auto import floor_area
    from thermoscene.energyplus.runner import find_energyplus
    from thermoscene.energyplus.topology import HVACGraph
    rec = dict(file=Path(idf).name)
    try:
        exe = find_energyplus(None)
        with tempfile.TemporaryDirectory() as tmp:
            model = pipeline.load_model(idf, exe, tmp)
        graph = HVACGraph(model)
        zones = model.zone_names()
        total = sum(floor_area(model, z) for z in zones)
        rec["signature"] = f"{len(zones)}z-{round(total / 5) * 5}m2"
        rng = np.random.default_rng(int(hashlib.md5(rec["file"].encode()).hexdigest()[:8], 16))
        best = None
        for z in zones:                                   # conditioned zones first; any zone if none qualifies
            conditioned = z.upper() in graph.zone_inlets
            walls = []
            for s in model.surfaces(z):
                if s["type"] != "Wall" or s["boundary"].lower() != "outdoors" or model.insulation_layer(s["construction"]) is None:
                    continue
                width, height, subs = _wall_rects(model, s)
                rect = place_defect(width, height, subs, rng)
                walls.append(dict(name=s["name"], rect=rect, width=round(width, 2), height=round(height, 2),
                                  windows=len(subs)))
            usable = [w for w in walls if w["rect"]]
            if not usable:
                continue
            key = (conditioned, len(usable), floor_area(model, z))
            if best is None or key > best[0]:
                best = (key, z, walls)
        if best is None:
            rec["error"] = "no zone with an insulated exterior wall that can take a void"
            return rec
        (conditioned, _, _), z, walls = best
        rec["conditioned"] = conditioned
        usable = [w for w in walls if w["rect"]]
        n_void = 1 if len(walls) < 2 else int(rng.integers(1, 3))
        order = rng.permutation(len(usable))[:n_void]
        rec.update(zone=z, area=round(floor_area(model, z), 1), exterior_walls=len(walls),
                   voids=[dict(surface=usable[i]["name"], rect=usable[i]["rect"]) for i in order])
    except Exception as e:  # noqa: BLE001
        rec["error"] = f"{type(e).__name__}: {e}"
    return rec


def stage_select(jobs, limit=None):
    from thermoscene.energyplus.runner import energyplus_dir, find_energyplus
    corpus = json.loads((ROOT / "case_studies" / "corpus_scenes.json").read_text(encoding="utf-8"))
    ex = energyplus_dir(find_energyplus(None)) / "ExampleFiles"
    files = [str(ex / f) for f, r in sorted(corpus.items()) if r["ok"] and not any(x in f for x in EXCLUDE)]
    files = files[:limit] if limit else files
    print(f"select: {len(files)} models", flush=True)
    with mp.Pool(jobs) as pool:
        recs = pool.map(select_one, files, chunksize=4)
    ok = [r for r in recs if "zone" in r]
    by_sig = {}
    for r in sorted(ok, key=lambda r: (-r["exterior_walls"], -r["area"], r["file"])):
        by_sig.setdefault(r["signature"], r)          # one model per building geometry
    chosen = sorted(by_sig.values(), key=lambda r: r["file"])
    OUT.mkdir(parents=True, exist_ok=True)
    (OUT / "select.json").write_text(json.dumps(dict(all=recs, chosen=chosen), indent=1), encoding="utf-8")
    print(f"select: {len(ok)} usable, {len(chosen)} distinct geometries", flush=True)


# ------------------------------------------------------------------------------------------------ build
def tag_of(rec):
    return Path(rec["file"]).stem[:32]


def build_one(rec: dict) -> dict:
    from thermoscene import auto, pipeline
    from thermoscene.energyplus.runner import energyplus_dir, find_energyplus
    out = OUT / "scenes" / tag_of(rec)
    done = out / "done.json"
    if done.exists():
        return json.loads(done.read_text(encoding="utf-8"))
    t0 = time.time()
    res = dict(file=rec["file"], tag=tag_of(rec))
    try:
        exe = find_energyplus(None)
        A = auto.auto_defaults()
        ex = energyplus_dir(exe)
        idf = ex / "ExampleFiles" / rec["file"]
        with tempfile.TemporaryDirectory() as tmp:
            model = pipeline.load_model(idf, exe, tmp)
        epw = auto.nearest_epw(auto.site_location(model), sorted((ex / A["weather_dir"]).glob("*.epw")), A["fallback_epw"])
        ts = max(auto.model_timesteps(model) or A["timesteps_per_hour"], A["min_timesteps_per_hour"])
        cfg = auto.case_config(idf, rec["zone"], epw, out, out / ".sim_cache", model, A, ts)
        cfg["name"] = "scene"
        cfg["faults"] = [dict(type="envelope_defect", surface=v["surface"], rect=v["rect"], name=f"Void_{i + 1}")
                         for i, v in enumerate(rec["voids"])]
        cfg["cameras"] = []
        auto.write_case(cfg, out / "case.yaml", "detector experiment: voids injected, no cameras")
        usd = pipeline.build(out / "case.yaml", render=False)
        res.update(usd=str(usd), epw=Path(epw).name, seconds=round(time.time() - t0, 1))
        done.write_text(json.dumps(res), encoding="utf-8")
    except Exception as e:  # noqa: BLE001
        res["error"] = f"{type(e).__name__}: {e}"
        res["trace"] = traceback.format_exc()[-1500:]
    return res


def stage_build(jobs, limit=None):
    chosen = json.loads((OUT / "select.json").read_text(encoding="utf-8"))["chosen"]
    chosen = chosen[:limit] if limit else chosen
    print(f"build: {len(chosen)} scenes, {jobs} workers", flush=True)
    res = []
    with mp.Pool(jobs) as pool:
        for r in pool.imap_unordered(build_one, chosen):
            res.append(r)
            print(f"[{len(res)}/{len(chosen)}] {r['file']}: {'ok' if 'usd' in r else r.get('error', '')[:150]}", flush=True)
    (OUT / "build.json").write_text(json.dumps(sorted(res, key=lambda r: r["file"]), indent=1), encoding="utf-8")


# ------------------------------------------------------------------------------------------------ render
def to_grid(a, mode="mean"):
    """Crop to 4:3 around the centre and average blocks down to H x W (all presets are integer multiples)."""
    h, w = a.shape
    ch = w * 3 // 4
    if ch < h:
        y0 = (h - ch) // 2
        a = a[y0:y0 + ch]
    f = a.shape[1] // W
    a = a[:H * f, :W * f].reshape(H, f, W, f)
    return a.mean(axis=(1, 3))


def aim(w, k, rng, d_range, hfov, space):
    """A pose 1-4 m from prim k at about eye height, with the target off-centre in the view."""
    from thermoscene.embodied.world import Pose
    for _ in range(4):
        p = w.view_of(k, float(rng.uniform(*d_range)), space=space, n_dirs=36)
        if p is None:
            continue
        c = (w.prim_lo[k] + w.prim_hi[k]) / 2
        eye = np.asarray(p.eye, float) + [0.0, 0.0, rng.uniform(-0.4, 0.4)]
        if w.space_at(eye) != space:
            eye = np.asarray(p.eye, float)
        f = c - eye
        dist = float(np.linalg.norm(f))
        f = f / dist
        right = np.cross(f, [0.0, 0.0, 1.0])
        right = right / (np.linalg.norm(right) or 1.0)
        up = np.cross(right, f)
        half = dist * np.tan(np.radians(hfov / 2))
        tgt = c + right * rng.uniform(-0.45, 0.45) * half + up * rng.uniform(-0.3, 0.3) * half
        return Pose.look_at(eye, tgt), dist
    return None, None


def contrasts(f, fi):
    """Void minus host wall (median over the void, median over a ring 2-6 pixels around it on the wall it sits in):
    true temperature, realistic reading, ideal reading; None without at least 4 void and 4 ring pixels."""
    from scipy.ndimage import binary_dilation
    F = f.fault & ~f.mixed
    if F.sum() < 4:
        return None, None, None
    ring = binary_dilation(f.fault, iterations=6) & ~binary_dilation(f.fault, iterations=2)
    inst = f.instance[ring]
    inst = inst[inst >= 0]
    if not len(inst):
        return None, None, None
    ring &= f.instance == np.bincount(inst).argmax()
    if ring.sum() < 4:
        return None, None, None
    d = lambda a: round(float(np.median(a[F]) - np.median(a[ring])), 3)
    return d(f.true), d(f.reading), d(fi.reading)


def render_one(res: dict) -> dict:
    from thermoscene.embodied import ThermalCamera, ThermalWorld
    out = OUT / "scenes" / res["tag"]
    npz = out / "views.npz"
    if npz.exists():
        return dict(tag=res["tag"], views=int(np.load(npz)["mask"].shape[0]), cached=True)
    t0 = time.time()
    try:
        w = ThermalWorld(res["usd"])
        space = w.space_path("Zone")
        rng = np.random.default_rng(int(hashlib.md5(res["tag"].encode()).hexdigest()[:8], 16))
        inzone = [k for k in range(len(w.prim_paths)) if w.space_of[k] == space and np.isfinite(w.prim_lo[k]).all()]
        voids = [k for k in inzone if w.fault[k]]
        others = [k for k in inzone if not w.fault[k]]
        cats = {}
        for k in others:
            cats.setdefault(int(w.cat[k]), []).append(k)
        names, probs = zip(*PRESETS)
        R, I, T, M, meta = [], [], [], [], []
        tex = int(rng.integers(1 << 30))
        while len(meta) < VIEWS:
            positive = voids and rng.random() < POS_SHARE
            if positive:
                k = int(rng.choice(voids))
            else:
                group = list(cats.values())[int(rng.integers(len(cats)))]
                k = int(rng.choice(group))
            preset = str(rng.choice(names, p=probs))
            cam = ThermalCamera.preset(preset, seed=int(rng.integers(1 << 30)), supersample=1).randomized(rng)
            pose, dist = aim(w, k, rng, (1.5, 4.5) if positive else (1.0, 4.5), cam.hfov, space)
            if pose is None:
                continue
            tc = int(rng.integers(w.n))
            f = w.observe(pose, tc, cam, space=space, rng=rng, frame_seed=int(rng.integers(1 << 30)), texture_seed=tex)
            ideal = ThermalCamera.preset("ideal", resolution=[cam.w, cam.h], hfov_deg=cam.hfov, supersample=1)
            fi = w.observe(pose, tc, ideal, space=space, realism=CLEAN)
            m = to_grid(f.fault.astype(float)) >= 0.5
            R.append(to_grid(f.reading)); I.append(to_grid(fi.reading)); T.append(to_grid(np.where(np.isfinite(f.true), f.true, np.nan)))
            M.append(m)
            ct, cr, ci = contrasts(f, fi)
            meta.append(dict(target=w.prim_paths[k].split("/")[-1], aimed_at_void=bool(positive), preset=preset,
                             distance_m=round(dist, 2), time=w.labels[tc], fault_px=int(m.sum()),
                             contrast_true_K=ct, contrast_read_K=cr, contrast_ideal_K=ci))
        T = np.array(T)
        T = np.where(np.isfinite(T), T, np.nanmedian(T))
        np.savez_compressed(npz, real=np.array(R, np.float32), ideal=np.array(I, np.float32), true=T.astype(np.float32),
                            mask=np.array(M, bool))
        (out / "views.json").write_text(json.dumps(meta, indent=0), encoding="utf-8")
        return dict(tag=res["tag"], views=len(meta), seconds=round(time.time() - t0, 1),
                    positives=int(sum(x["fault_px"] >= 4 for x in meta)))
    except Exception as e:  # noqa: BLE001
        return dict(tag=res["tag"], error=f"{type(e).__name__}: {e}", trace=traceback.format_exc()[-1500:])


def stage_render(jobs, limit=None):
    built = [r for r in json.loads((OUT / "build.json").read_text(encoding="utf-8")) if "usd" in r]
    built = built[:limit] if limit else built
    print(f"render: {len(built)} scenes x {VIEWS} views, {jobs} workers", flush=True)
    res = []
    with mp.Pool(jobs) as pool:
        for r in pool.imap_unordered(render_one, built):
            res.append(r)
            print(f"[{len(res)}/{len(built)}] {r['tag']}: {r.get('views', r.get('error', '')[:150])} "
                  f"({r.get('seconds', 'cached')} s)", flush=True)
    (OUT / "render.json").write_text(json.dumps(sorted(res, key=lambda r: r["tag"]), indent=1), encoding="utf-8")


# ------------------------------------------------------------------------------------------------ split
def stage_split(test_share=0.3, val_share=0.1):
    sel = {r["file"]: r for r in json.loads((OUT / "select.json").read_text(encoding="utf-8"))["chosen"]}
    built = {r["tag"]: r for r in json.loads((OUT / "build.json").read_text(encoding="utf-8")) if "usd" in r}
    rendered = [r["tag"] for r in json.loads((OUT / "render.json").read_text(encoding="utf-8")) if "views" in r]
    tags = sorted(t for t in rendered if t in built)
    rng = np.random.default_rng(SEED)
    order = [tags[i] for i in rng.permutation(len(tags))]
    n_test, n_val = round(test_share * len(order)), round(val_share * len(order))
    split = dict(test=sorted(order[:n_test]), val=sorted(order[n_test:n_test + n_val]), train=sorted(order[n_test + n_val:]))
    split["meta"] = {t: dict(file=built[t]["file"], signature=sel[built[t]["file"]]["signature"], zone=sel[built[t]["file"]]["zone"],
                             epw=built[t].get("epw")) for t in tags}
    (OUT / "split.json").write_text(json.dumps(split, indent=1), encoding="utf-8")
    print({k: len(v) for k, v in split.items() if k != "meta"})


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("stage", choices=["select", "build", "render", "split", "all"])
    ap.add_argument("--jobs", type=int, default=5)
    ap.add_argument("--limit", type=int)
    a = ap.parse_args()
    for s in (["select", "build", "render", "split"] if a.stage == "all" else [a.stage]):
        t = time.time()
        {"select": lambda: stage_select(a.jobs, a.limit), "build": lambda: stage_build(a.jobs, a.limit),
         "render": lambda: stage_render(a.jobs, a.limit), "split": stage_split}[s]()
        print(f"{s}: {time.time() - t:.0f} s", flush=True)
